START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261121125209_AddStrikeAttestation') THEN
    CREATE TABLE adaptive_strike_attestation (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "SessionId" bigint NOT NULL,
        "BarSeq" integer NOT NULL,
        "MetricsVersion" character varying(64) NOT NULL,
        "TokenCount" integer NOT NULL,
        "Digests" text NOT NULL,
        "VerifiedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_adaptive_strike_attestation" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_adaptive_strike_attestation_adaptive_sessions_SessionId" FOREIGN KEY ("SessionId") REFERENCES adaptive_sessions ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261121125209_AddStrikeAttestation') THEN
    CREATE UNIQUE INDEX "IX_adaptive_strike_attestation_SessionId_BarSeq_MetricsVersion" ON adaptive_strike_attestation ("SessionId", "BarSeq", "MetricsVersion");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261121125209_AddStrikeAttestation') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261121125209_AddStrikeAttestation', '10.0.11');
    END IF;
END $EF$;
COMMIT;

